import Foundation

/// A network subtitle file (`MediaLoadRequest.SubtitleFile`), downloaded and read when its track is selected.
struct RemoteSubtitle: Sendable {
    let url: URL
    let headers: [String: String]
    let format: SubtitleFormat
    /// Auto-generated captions, whose WebVTT rolls up (`SubtitleDocument.parseWebVTT`).
    let isAutoGenerated: Bool
    /// The video's, for MicroDVD (`FFmpegTextSubtitles.read`).
    let frameRate: Double?
    let hints: TextFileEncoding.Hints

    /// Larger isn't a subtitle file: hours of dialogue are a few megabytes.
    static let sizeLimit = 20 << 20

    /// The file's cues: SRT, WebVTT or ASS parsed here, the formats FFmpeg reads by FFmpeg (also for a URL whose
    /// extension doesn't tell, when the text isn't SRT). `nil` when the download fails or the body holds no cue (an
    /// error page answered with 200).
    func read(interrupt: FFmpegInterrupt) async -> SubtitleDocument? {
        guard let data = await download() else { return nil }
        let readByFFmpeg = {
            FFmpegTextSubtitles.read(data: data, of: url, frameRate: frameRate, hints: hints, interrupt: interrupt)
        }
        let document: SubtitleDocument?
        if FFmpegTextSubtitles.extensions.contains(url.pathExtension.lowercased()) {
            document = readByFFmpeg()
        } else {
            let parsed = SubtitleController.parseTextSubtitle(
                data: data, url: url, format: format, collapsingRollUp: isAutoGenerated, hints: hints)
            document = parsed.flatMap { $0.cues.isEmpty ? nil : $0 } ?? (format == .ass ? nil : readByFFmpeg())
        }
        guard let document, !document.cues.isEmpty else {
            AppLog.warning(.subtitles, "No subtitles in \(url.absoluteString.prefix(200))")
            return nil
        }
        return document
    }

    /// The file's bytes. Tried again once only when it may pass the next time: a network error or a server error
    /// (5xx), not another status or a body past `sizeLimit`.
    private func download() async -> Data? {
        var request = URLRequest(url: url, timeoutInterval: 15)
        for (name, value) in headers {
            request.setValue(value, forHTTPHeaderField: name)
        }
        let described = url.absoluteString.prefix(200)
        for attempt in 1...2 {
            if attempt > 1 { try? await Task.sleep(for: .milliseconds(250)) }
            guard !Task.isCancelled else { return nil }
            let bytes: URLSession.AsyncBytes
            let response: URLResponse
            do {
                (bytes, response) = try await URLSession.shared.bytes(for: request)
            } catch {
                if Self.isCancellation(error) { return nil }
                AppLog.warning(.subtitles, "Can't download subtitles \(described): \(error.localizedDescription)")
                continue
            }
            let status = (response as? HTTPURLResponse)?.statusCode ?? 200
            if (500..<600).contains(status) {
                AppLog.warning(.subtitles, "Subtitles \(described) answered HTTP \(status)")
                continue
            }
            guard (200..<300).contains(status) else {
                AppLog.warning(.subtitles, "Subtitles \(described) answered HTTP \(status)")
                return nil
            }
            guard response.expectedContentLength <= Self.sizeLimit else {
                AppLog.warning(.subtitles, "Subtitles \(described) are too large: \(response.expectedContentLength) B")
                return nil
            }
            var data = Data()
            do {
                for try await byte in bytes {
                    data.append(byte)
                    guard data.count <= Self.sizeLimit else {
                        AppLog.warning(.subtitles, "Subtitles \(described) are larger than \(Self.sizeLimit) B")
                        return nil
                    }
                }
            } catch {
                if Self.isCancellation(error) { return nil }
                AppLog.warning(.subtitles, "Can't download subtitles \(described): \(error.localizedDescription)")
                continue
            }
            return data.isEmpty ? nil : data
        }
        return nil
    }

    /// The read was cancelled (another track selected): nothing to report or try again.
    private static func isCancellation(_ error: any Error) -> Bool {
        Task.isCancelled || error is CancellationError || (error as? URLError)?.code == .cancelled
    }
}
